-- Schema-only fixture captured from production 2026-10-26; no customer data.
do $$ begin
 begin create role anon;exception when duplicate_object or unique_violation then null;end;
 begin create role authenticated;exception when duplicate_object or unique_violation then null;end;
 begin create role service_role;exception when duplicate_object or unique_violation then null;end;
end $$;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$ select nullif(current_setting('test.actor',true),'')::uuid $$;
create function public.sc_current_app_role() returns text language sql stable as $$ select current_setting('test.role',true) $$;
create function public.sc_internal_access_allowed(text[]) returns boolean language sql stable as $$ select coalesce(public.sc_current_app_role()=any($1),false) $$;
create table public.blank_products (
 "id" uuid primary key default gen_random_uuid(),
 "sku_base" text,
