 "brand_id" int8,
 "product_type_id" int8,
 "color_id" int8,
 "size_id" int8,
 "image_url" text,
 "created_at" timestamptz default now(),
 "barcode" text,
 "unit_cost" numeric default 0,
 "low_stock_threshold" int4 default 0,
 "updated_at" timestamptz,
 "supplier" text,
 "supplier_sku" text,
 "notes" text,
 "master_source" text default 'manual'::text,
 "master_imported_at" timestamptz,
 "master_import_file" text,
 "is_active" bool default true,
 "upc" text,
 "supplier_id" uuid,
 "vendor_sku" text,
 "case_pack_qty" int4,
 "manufacturer_sku" text,
 "sc_is_archived" bool default false,
 "sc_archived_at" timestamptz,
 "sc_archived_by" uuid,
 "sc_archived_reason" text,
 "sc_archived_original_sku" text,
 "sc_archived_original_barcode" text,
 "sc_archived_original_name" text,
 "sc_canonical_blank_product_id" uuid,
 "sc_product_line_setup_id" uuid,
 "sc_cost_review_required" bool default false,
 "sc_creation_source" text,
 "image_storage_provider" text,
 "image_storage_bucket" text,
 "image_storage_path" text,
 "image_file_size_bytes" int8,
 "image_mime_type" text,
 "image_preview_storage_provider" text,
 "image_preview_storage_bucket" text,
 "image_preview_storage_path" text,
 "image_preview_size_bytes" int8
);
